<script setup lang="ts">import type{Article,Question}from'@career-launch/shared';import{onMounted,ref}from'vue';import{repository}from'../../services/repository';const tab=ref<'articles'|'questions'>('articles');const articles=ref<Article[]>([]);const questions=ref<Question[]>([]);async function load(){articles.value=(await repository.admin.articles.list({page:1,pageSize:100})).items;questions.value=(await repository.admin.questions.list({page:1,pageSize:100})).items}onMounted(load)</script>
<template><section><header class="admin-page-head"><div><h1>面试内容</h1><p>维护官方攻略和结构化面试题库。</p></div><button class="cl-primary-button">{{tab==='articles'?'新建文章':'录入题目'}}</button></header><div class="admin-toolbar"><button class="cl-quiet-button" :class="{active:tab==='articles'}" @click="tab='articles'">攻略文章 {{articles.length}}</button><button class="cl-quiet-button" :class="{active:tab==='questions'}" @click="tab='questions'">面试题库 {{questions.length}}</button><input placeholder="搜索内容"/></div><div class="admin-table-wrap"><table v-if="tab==='articles'" class="admin-table"><thead><tr><th>标题</th><th>分类</th><th>阅读时长</th><th>发布时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in articles" :key="item.id"><td><strong>{{item.title}}</strong></td><td>{{item.category}}</td><td>{{item.readingMinutes}} 分钟</td><td>{{new Date(item.publishedAt).toLocaleDateString('zh-CN')}}</td><td>已发布</td><td><button class="admin-link-button">编辑</button></td></tr></tbody></table><table v-else class="admin-table"><thead><tr><th>题目</th><th>分类</th><th>环节</th><th>难度</th><th>操作</th></tr></thead><tbody><tr v-for="item in questions" :key="item.id"><td>{{item.prompt}}</td><td>{{item.category}}</td><td>{{item.stage}}</td><td>{{item.difficulty}}</td><td><button class="admin-link-button">编辑</button></td></tr></tbody></table></div></section></template><style scoped>.admin-toolbar .active{color:var(--cl-primary);border-color:var(--cl-primary)}</style>
